package com.ecole.gestion_scolaire.teacherportal.entity;
import com.ecole.gestion_scolaire.hr.entity.*; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="teacher_exercise") public class TeacherExercise { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teacher_id") private Teacher teacher; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teaching_assignment_id") private TeachingAssignment assignment; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="text") private String description; @Column(columnDefinition="text") private String instructions; private LocalDate dueDate; private String attachmentReference; @Column(nullable=false,length=30) private String status="DRAFT"; private OffsetDateTime createdAt; private OffsetDateTime updatedAt; @PrePersist void pre(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Long getId(){return id;} public Teacher getTeacher(){return teacher;} public void setTeacher(Teacher v){teacher=v;} public TeachingAssignment getAssignment(){return assignment;} public void setAssignment(TeachingAssignment v){assignment=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getInstructions(){return instructions;} public void setInstructions(String v){instructions=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public String getAttachmentReference(){return attachmentReference;} public void setAttachmentReference(String v){attachmentReference=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
